#!/usr/bin/env python3
import sys
import openpyxl

def main():
    spreadsheet_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(spreadsheet_path)
    ws = wb["Sheet1"]

    # Build list of output entries from column A (company) and column B (count).
    out = []
    row = 2
    while True:
        name = ws.cell(row=row, column=1).value
        count = ws.cell(row=row, column=2).value
        if name is None or count is None:
            break
        try:
            n = int(float(count))
        except (TypeError, ValueError):
            n = 0
        if n > 0:
            out.extend([name] * n)
        row += 1

    # Write the expanded list into column D starting at D2.
    for i, val in enumerate(out):
        ws.cell(row=2 + i, column=4).value = val

    wb.save(output_path)

if __name__ == "__main__":
    main()

